#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=7

banner "ZBEar: deploy to Cloudflare Pages behind Cloudflare Access (ticket #3)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Workers KV: create the namespace"
say "This key-value store will later hold your personal data (home Origin, Curated"
say "Parking Candidates) behind the login. It is never committed to the repo."
open_url "https://dash.cloudflare.com/?to=/:account/workers/kv/namespaces"
note "Already created a 'zbear' namespace on an earlier run? Keep it and skip this stage."
step "Pick your account if asked, then select 'Create instance'."
step "Name it: zbear"
step "Select 'Create'."
pause "Done? Press Enter."

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Pages: create the project from GitHub"
open_url "https://dash.cloudflare.com/?to=/:account/workers-and-pages"
step "Select 'Create application', switch to the Pages option (it may be a tab or a 'Pages' link; don't take the Workers flow), then 'Connect to Git'."
step "Choose GitHub → 'Install & Authorize' (grant access to swaree/ZBEar) → 'Begin setup'."
step "Project name: zbear   ·   Production branch: main"
step "Framework preset: None"
step "Build command: npm run build   ·   Build output directory: dist"
note "Node 22 comes from the repo's .node-version file; no variable needed."
warn "Wrong turn check: if you see 'Import a repository', a 'Deploy command' field, or the address will end in .workers.dev, you are creating a Worker, not a Pages project. Go back and pick Pages. (A Worker with only static assets cannot use the KV binding.)"
step "Select 'Save and Deploy' and wait for the first deployment to finish."
say ""
say "When it's done, Cloudflare shows the site address (e.g. zbear.pages.dev;"
say "it gets a suffix if 'zbear' was taken)."
ZBEAR_PAGES_HOST=""
while [[ "$ZBEAR_PAGES_HOST" != *.pages.dev ]]; do
  ask ZBEAR_PAGES_HOST "Paste the host, without https:// (e.g. zbear.pages.dev):"
  ZBEAR_PAGES_HOST="${ZBEAR_PAGES_HOST#http*://}"; ZBEAR_PAGES_HOST="${ZBEAR_PAGES_HOST%%/*}"
  if [[ "$ZBEAR_PAGES_HOST" == *.workers.dev ]]; then
    warn "That's a Worker address: delete that Worker (its Settings → Delete) and create a Pages project as above."
  elif [[ "$ZBEAR_PAGES_HOST" != *.pages.dev ]]; then
    warn "Expected an address ending in .pages.dev."
  fi
done
write_env ZBEAR_PAGES_HOST "$ZBEAR_PAGES_HOST"
warn "Until stage 5 the site is public. Nothing personal is in it yet."

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Pages: bind the KV namespace"
open_url "https://dash.cloudflare.com/?to=/:account/workers-and-pages"
step "Open the zbear project → 'Settings' → 'Bindings' → 'Add' → 'KV namespace'."
step "Variable name: ZBEAR_KV   ·   KV namespace: zbear"
step "Save. If the page has a Production/Preview switch, add the same binding to both."
step "Redeploy so the binding takes effect: 'Deployments' → latest production deployment → '…' menu → 'Retry deployment'."
pause "Done, and the redeploy finished? Press Enter."

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Zero Trust: onboarding and one-time email codes"
open_url "https://one.dash.cloudflare.com/"
step "If this is your first time: choose a team name, then the 'Zero Trust Free' plan."
note "Cloudflare asks for payment details even on Free; the Free plan is not charged."
step "Then: 'Integrations' → 'Identity providers' → 'Add new identity provider' → 'One-time PIN' → Save."
note "New organisations don't get One-time PIN automatically, so this step matters."
pause "Done? Press Enter."

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Access: put the whole site behind the login"
say "Cloudflare's 'Enable access policy' toggle alone only protects previews;"
say "these steps (from Cloudflare's Pages known-issues page) cover $ZBEAR_PAGES_HOST too."
open_url "https://dash.cloudflare.com/?to=/:account/workers-and-pages"
step "zbear project → 'Settings' → General → 'Enable access policy'."
step "Select 'Manage' on the policy it created (opens Zero Trust)."
step "In the application: under 'Public hostname', delete the wildcard * in 'Subdomain' so it covers $ZBEAR_PAGES_HOST itself. Rename the application (e.g. 'ZBEar production') and Save."
step "Check its policy is 'Allow' with an Emails rule containing ONLY your email."
step "Check its login methods include 'One-time PIN' (or that it accepts all identity providers)."
step "Previews: if the Pages project's Settings → General offers 'Enable access policy' again, select it. If it doesn't, in Zero Trust create another self-hosted application for *.$ZBEAR_PAGES_HOST with the same Allow policy."
pause "Done? Press Enter."

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Mapbox: account for traffic-aware driving (used from ticket #7)"
open_url "https://account.mapbox.com/auth/signup/"
step "Sign up and choose to start WITHOUT a credit card (demo access)."
note "No token is needed yet; ticket #7 will ask for one. Nothing to copy now."
pause "Done (or skipped for later)? Press Enter."

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Check: the login wall and the key-value store"
say "Requesting https://$ZBEAR_PAGES_HOST/ without logging in…"
check_locked() {
  local path="$1" code location
  read -r code location < <(curl -sS -o /dev/null -w '%{http_code} %{redirect_url}\n' "https://$ZBEAR_PAGES_HOST$path" || echo "000 -")
  if [[ "$code" =~ ^30[1-8]$ && "$location" == *cloudflareaccess.com* ]]; then
    printf '  %s✓%s %s → login redirect\n' "$GREEN" "$RESET" "$path"
  else
    warn "$path answered $code ${location:-} (expected a redirect to *.cloudflareaccess.com)"
    SKIPPED+=("Access is not protecting $path yet: recheck stage 5")
  fi
}
check_locked "/"
check_locked "/api/health"
check_locked "/index.html"
check_locked "/assets/index.js"
say ""
step "Now on your phone: open https://$ZBEAR_PAGES_HOST and log in with the emailed code,"
step "and plan a Trip: Origin and Destination as 'lat, lng' coordinates (e.g. 41.387, 2.170), arrive-by within the next 3 days."
step "Then open https://$ZBEAR_PAGES_HOST/api/health, which should show {\"ok\":true,\"kv\":\"ok\",…}"
if ! confirm "Did the Trip work and /api/health show ok:true?"; then
  SKIPPED+=("Phone check failed: if /api/health says 'missing ZBEAR_KV binding', redo stage 3 and redeploy")
fi

SKIPPED+=("Later: email the Transitous maintainers about this personal, open-source use (skipped by choice for now)")

finish
}

run_wizard "$@"; exit
